const FRAGEN = [
  // ───────── GESCHICHTE ─────────
  { id: 'g1', k: 'geschichte', t: 'mc', n: 1, f: 'In welchem Jahr fiel die Berliner Mauer?', a: '1989', x: ['1987', '1990', '1991'], tx: ['1989'],
    e: 'Am 9. November 1989 wurde die Grenze nach einer missverständlichen Pressekonferenz geöffnet. Warum wichtig: Der Mauerfall leitete das Ende der DDR ein, 1990 folgte die deutsche Wiedervereinigung.', q: W + 'Berliner_Mauer' },
  { id: 'g2', k: 'geschichte', t: 'mc', n: 1, f: 'Wer betrat 1969 als erster Mensch den Mond?', a: 'Neil Armstrong', x: ['Buzz Aldrin', 'Juri Gagarin', 'John Glenn'], tx: ['Armstrong', 'Neil Armstrong'],
    e: 'Mit Apollo 11 landeten Armstrong und Buzz Aldrin auf dem Mond, Aldrin stieg als Zweiter aus. Juri Gagarin war 1961 der erste Mensch im Weltall. Warum: Die USA gewannen damit den „Wettlauf ins All“ gegen die Sowjetunion.', q: W + 'Apollo_11' },
  { id: 'g3', k: 'geschichte', t: 'reihe', n: 2, f: 'Ordne chronologisch (früheste zuerst):', r: ['Französische Revolution (1789)', 'Wiener Kongress (1814/15)', 'Revolutionen in Europa (1848)', 'Beginn Erster Weltkrieg (1914)'],
    e: 'Die Französische Revolution stürzte die Monarchie. Nach Napoleons Niederlage ordnete der Wiener Kongress Europa neu. 1848 kam es in vielen Ländern zu Aufständen für Verfassungen und Freiheitsrechte, auch in Wien. 1914 begann der Erste Weltkrieg.', q: W + 'Wiener_Kongress' },
  { id: 'g4', k: 'geschichte', t: 'mc', n: 1, f: 'Welches Ereignis gilt als Auslöser des Ersten Weltkriegs?', a: 'Das Attentat von Sarajevo auf Erzherzog Franz Ferdinand', x: ['Der Untergang der Titanic', 'Die Ermordung von Kaiserin Elisabeth', 'Der Einmarsch in Polen'], tx: ['Attentat von Sarajevo', 'Sarajevo', 'Attentat auf Franz Ferdinand', 'Franz Ferdinand'],
    e: 'Am 28. Juni 1914 erschoss Gavrilo Princip den österreichisch-ungarischen Thronfolger. Warum der Krieg folgte: Bündnisse zogen innerhalb weniger Wochen die Großmächte hinein. Der Einmarsch in Polen 1939 begann dagegen den Zweiten Weltkrieg.', q: W + 'Attentat_von_Sarajevo' },
  { id: 'g5', k: 'geschichte', t: 'mc', n: 1, f: 'In welchem Jahr begann der Zweite Weltkrieg in Europa?', a: '1939', x: ['1938', '1940', '1941'], tx: ['1939'],
    e: 'Mit dem deutschen Überfall auf Polen am 1. September 1939 begann der Krieg, Großbritannien und Frankreich erklärten daraufhin den Krieg. 1938 war der „Anschluss“ Österreichs. In Europa endete der Krieg am 8. Mai 1945.', q: W + 'Zweiter_Weltkrieg' },
  { id: 'g6', k: 'geschichte', t: 'wf', n: 2, f: 'Kolumbus erreichte 1492 Amerika und glaubte, in Asien („Indien“) angekommen zu sein.', w: true,
    e: 'Stimmt. Kolumbus suchte einen Seeweg nach Westen nach Asien und landete auf einer Insel der Bahamas. Deshalb wurden die Ureinwohner „Indianer“ genannt. Dass es ein neuer Kontinent war, setzte sich erst später durch, unter anderem durch Amerigo Vespucci, der dem Kontinent den Namen gab.', q: W + 'Christoph_Kolumbus' },
  { id: 'g7', k: 'geschichte', t: 'mc', n: 2, f: 'In welchem Jahr endete das Weströmische Reich mit der Absetzung des letzten Kaisers?', a: '476', x: ['410', '395', '800'], tx: ['476'],
    e: '476 setzte der germanische Heerführer Odoaker den Kaiser Romulus Augustulus ab. Das Jahr gilt oft als Ende der Antike. 410 plünderten die Westgoten Rom, 395 wurde das Reich geteilt, 800 wurde Karl der Große zum Kaiser gekrönt. Das Oströmische Reich bestand bis 1453.', q: W + 'Weströmisches_Reich' },
  { id: 'g8', k: 'geschichte', t: 'mc', n: 1, f: 'Wer erfand um 1450 den Buchdruck mit beweglichen Lettern in Europa?', a: 'Johannes Gutenberg', x: ['Martin Luther', 'Leonardo da Vinci', 'Albrecht Dürer'], tx: ['Gutenberg', 'Johannes Gutenberg'],
    e: 'Gutenberg druckte in Mainz unter anderem die berühmte Gutenberg-Bibel. Warum wichtig: Bücher und Flugschriften wurden billig und schnell vervielfältigt. Das half zum Beispiel, Luthers Reformation rasch zu verbreiten.', q: W + 'Johannes_Gutenberg' },
  { id: 'g9', k: 'geschichte', t: 'mc', n: 2, f: 'Welcher Pharao wurde durch sein 1922 fast unberührt entdecktes Grab berühmt?', a: 'Tutanchamun', x: ['Ramses II.', 'Cheops', 'Echnaton'], tx: ['Tutanchamun', 'Tut-anch-Amun'],
    e: 'Howard Carter fand das Grab im Tal der Könige mit der berühmten goldenen Totenmaske. Warum berühmt: Fast alle anderen Pharaonengräber waren längst ausgeraubt. Tutanchamun selbst war ein eher unbedeutender, jung gestorbener König.', q: W + 'Tutanchamun' },
  { id: 'g10', k: 'geschichte', t: 'mc', n: 3, f: 'In welchem Jahr zerfiel die Sowjetunion?', a: '1991', x: ['1989', '1985', '1995'], tx: ['1991'],
    e: 'Im Dezember 1991 löste sich die UdSSR in 15 unabhängige Staaten auf, darunter Russland und die Ukraine. Damit war auch der Kalte Krieg zu Ende. 1989 fiel die Berliner Mauer, 1985 kam Gorbatschow an die Macht.', q: W + 'Zerfall_der_Sowjetunion' },
  { id: 'g11', k: 'geschichte', t: 'wf', n: 3, f: 'Die Magna Carta wurde 1215 in England besiegelt.', w: true,
    e: 'Stimmt. Adelige zwangen König Johann Ohneland, seine Macht zu beschränken, zum Beispiel durfte niemand ohne Gerichtsurteil eingesperrt werden. Warum wichtig: Sie gilt als frühes Vorbild für Grundrechte und Verfassungen.', q: W + 'Magna_Carta' },

  // ───────── GEOGRAFIE ─────────
  { id: 'geo1', k: 'geografie', t: 'mc', n: 1, f: 'Welcher ist der längste Fluss Europas?', a: 'Wolga', x: ['Donau', 'Rhein', 'Dnepr'], tx: ['Wolga'],
    e: 'Die Wolga fließt rund 3.500 km durch Russland ins Kaspische Meer. Die Donau ist mit rund 2.850 km der zweitlängste Fluss Europas.', q: W + 'Wolga' },
  { id: 'geo2', k: 'geografie', t: 'mc', n: 1, f: 'Welcher ist der höchste Berg der Erde?', a: 'Mount Everest', x: ['K2', 'Kangchendzönga', 'Mont Blanc'], tx: ['Mount Everest', 'Everest', 'Mt Everest', 'Chomolungma'],
    e: 'Der Everest im Himalaya an der Grenze von Nepal und China ist rund 8.849 m hoch. Warum so hoch: Die Indische Platte schiebt sich gegen die Eurasische und faltet das Gebirge bis heute auf. Der K2 ist mit 8.611 m der zweithöchste.', q: W + 'Mount_Everest' },
  { id: 'geo3', k: 'geografie', t: 'mc', n: 2, f: 'Was ist die Hauptstadt Australiens?', a: 'Canberra', x: ['Sydney', 'Melbourne', 'Perth'], tx: ['Canberra'],
    e: 'Sydney und Melbourne stritten um den Titel. Als Kompromiss wurde dazwischen eine neue Hauptstadt geplant und gebaut: Canberra, Parlamentssitz seit 1927.', q: W + 'Canberra' },
  { id: 'geo4', k: 'geografie', t: 'mc', n: 1, f: 'Welcher ist der größte Ozean der Erde?', a: 'Pazifik', x: ['Atlantik', 'Indischer Ozean', 'Arktischer Ozean'], tx: ['Pazifik', 'Pazifischer Ozean', 'Stiller Ozean'],
    e: 'Der Pazifik bedeckt etwa ein Drittel der Erdoberfläche, mehr als alle Landflächen zusammen. Dort liegt auch die tiefste Stelle der Meere, der Marianengraben mit rund 11 km.', q: W + 'Pazifischer_Ozean' },
  { id: 'geo5', k: 'geografie', t: 'mc', n: 1, f: 'Welches ist das flächenmäßig größte Land der Welt?', a: 'Russland', x: ['Kanada', 'China', 'USA'], tx: ['Russland'],
    e: 'Russland ist mit rund 17 Mio. km² fast doppelt so groß wie Kanada auf Platz 2 und erstreckt sich über 11 Zeitzonen.', q: W + 'Russland' },
  { id: 'geo6', k: 'geografie', t: 'wf', n: 2, f: 'Die Sahara ist die größte Wüste der Welt.', w: false,
    e: 'Falsch, zumindest streng genommen. Eine Wüste wird über wenig Niederschlag definiert, nicht über Hitze. Die größte Wüste ist daher die Antarktis (Kältewüste). Die Sahara ist die größte heiße Wüste beziehungsweise Trockenwüste.', q: W + 'Wüste' },
  { id: 'geo7', k: 'geografie', t: 'mc', n: 2, f: 'Durch wie viele Länder fließt die Donau (inklusive Grenzabschnitte)?', a: '10', x: ['6', '8', '12'], tx: ['10', 'zehn'],
    e: 'Die zehn Länder sind Deutschland, Österreich, Slowakei, Ungarn, Kroatien, Serbien, Rumänien, Bulgarien, Moldau und Ukraine. Kein Fluss der Welt fließt durch mehr Länder. Sie verbindet auch vier Hauptstädte: Wien, Bratislava, Budapest und Belgrad.', q: W + 'Donau' },
  { id: 'geo8', k: 'geografie', t: 'mc', n: 2, f: 'Was ist die Hauptstadt Kanadas?', a: 'Ottawa', x: ['Toronto', 'Montreal', 'Vancouver'], tx: ['Ottawa'],
    e: 'Ottawa liegt an der Grenze zwischen dem englischsprachigen Ontario und dem französischsprachigen Québec. Das war mit ein Grund für die Wahl als Hauptstadt. Toronto ist die größte Stadt.', q: W + 'Ottawa' },
  { id: 'geo9', k: 'geografie', t: 'reihe', n: 3, f: 'Ordne die Kontinente nach Fläche (größter zuerst):', r: ['Asien', 'Afrika', 'Nordamerika', 'Südamerika'],
    e: 'Asien ist mit rund 44 Mio. km² der mit Abstand größte Kontinent. Dann folgen Afrika (ca. 30), Nordamerika (ca. 25) und Südamerika (ca. 18). Danach kommen Antarktis, Europa und Australien.', q: W + 'Kontinent' },
  { id: 'geo10', k: 'geografie', t: 'mc', n: 2, f: 'Welches Land hat die meisten Einwohner?', a: 'Indien', x: ['China', 'USA', 'Indonesien'], tx: ['Indien'], st: 2025, ab: '2029-12-31',
    e: 'Laut UN-Schätzungen hat Indien 2023 China überholt, beide haben über 1,4 Milliarden Einwohner. Warum: Chinas Bevölkerung schrumpft (Folge der früheren Ein-Kind-Politik und niedriger Geburtenrate), Indiens wächst noch.', q: W + 'Indien' },
  { id: 'geo11', k: 'geografie', t: 'mc', n: 2, f: 'Welche Meerenge trennt Spanien von Marokko?', a: 'Straße von Gibraltar', x: ['Bosporus', 'Ärmelkanal', 'Straße von Messina'], tx: ['Straße von Gibraltar', 'Gibraltar', 'Strasse von Gibraltar'],
    e: 'An der engsten Stelle trennen nur rund 14 km Europa und Afrika. Hier verbindet sich das Mittelmeer mit dem Atlantik. Der Bosporus trennt in Istanbul Europa von Asien.', q: W + 'Straße_von_Gibraltar' },

  // ───────── NATURWISSENSCHAFT & TECHNIK ─────────
  { id: 'n1', k: 'natur', t: 'mc', n: 1, f: 'Welches chemische Symbol hat Gold?', a: 'Au', x: ['Ag', 'Go', 'Gd'], tx: ['Au'],
    e: 'Au kommt vom lateinischen „aurum“. Ag ist Silber (lat. „argentum“). Warum lateinisch: Die Symbole wurden im 19. Jahrhundert international einheitlich nach den lateinischen Namen vergeben.', q: W + 'Gold' },
  { id: 'n2', k: 'natur', t: 'mc', n: 1, f: 'Wie schnell ist Licht im Vakuum ungefähr?', a: 'ca. 300.000 km pro Sekunde', x: ['ca. 30.000 km pro Sekunde', 'ca. 3.000 km pro Sekunde', 'ca. 300.000 km pro Stunde'],
    e: 'Genau sind es 299.792,458 km/s. Sonnenlicht braucht damit gut 8 Minuten bis zur Erde. Wir sehen die Sonne also immer so, wie sie vor 8 Minuten war.', q: W + 'Lichtgeschwindigkeit' },
  { id: 'n3', k: 'natur', t: 'mc', n: 1, f: 'Welcher Planet ist der Sonne am nächsten?', a: 'Merkur', x: ['Venus', 'Mars', 'Erde'], tx: ['Merkur'],
    e: 'Merkur ist auch der kleinste Planet. Heißester Planet ist aber die Venus. Warum: Ihre dichte CO₂-Atmosphäre erzeugt einen extremen Treibhauseffekt mit über 400 °C.', q: W + 'Merkur_(Planet)' },
  { id: 'n4', k: 'natur', t: 'mc', n: 1, f: 'Wer entwickelte die Relativitätstheorie?', a: 'Albert Einstein', x: ['Isaac Newton', 'Niels Bohr', 'Max Planck'], tx: ['Einstein', 'Albert Einstein'],
    e: 'Die spezielle Relativitätstheorie stammt von 1905, die allgemeine von 1915. Daraus folgt etwa, dass Zeit bei hoher Geschwindigkeit und in starker Schwerkraft langsamer vergeht. GPS-Satelliten müssen das sogar korrigieren.', q: W + 'Albert_Einstein' },
  { id: 'n5', k: 'natur', t: 'wf', n: 2, f: 'Diamant und Graphit (Bleistiftmine) bestehen beide aus reinem Kohlenstoff.', w: true,
    e: 'Stimmt. Der Unterschied liegt nur in der Anordnung der Atome. Im Diamant ist jedes Atom fest mit vier Nachbarn verbunden, deshalb ist er extrem hart. Graphit besteht aus Schichten, die leicht abgleiten. Darum schreibt ein Bleistift.', q: W + 'Diamant' },
  { id: 'n6', k: 'natur', t: 'mc', n: 1, f: 'Woraus besteht ein Wassermolekül (H₂O)?', a: '2 Wasserstoffatome und 1 Sauerstoffatom', x: ['1 Wasserstoffatom und 2 Sauerstoffatome', '2 Wasserstoffatome und 1 Stickstoffatom', '2 Heliumatome und 1 Sauerstoffatom'],
    e: 'Weil das Molekül gewinkelt ist, hat es eine leicht positive und eine leicht negative Seite. Daher kommen viele Besonderheiten von Wasser: Es löst gut, und Eis ist leichter als flüssiges Wasser und schwimmt.', q: W + 'Wasser' },
  { id: 'n7', k: 'natur', t: 'mc', n: 2, f: 'Wer entdeckte 1928 das Penicillin?', a: 'Alexander Fleming', x: ['Louis Pasteur', 'Robert Koch', 'Marie Curie'], tx: ['Fleming', 'Alexander Fleming'],
    e: 'Fleming bemerkte zufällig, dass ein Schimmelpilz auf einer Bakterienkultur die Bakterien abtötete. Warum wichtig: Penicillin war das erste breit eingesetzte Antibiotikum und hat Millionen Leben gerettet.', q: W + 'Alexander_Fleming' },
  { id: 'n8', k: 'natur', t: 'mc', n: 3, f: 'Wie viele Knochen hat ein erwachsener Mensch ungefähr?', a: '206', x: ['186', '226', '256'], tx: ['206'],
    e: 'Neugeborene haben deutlich mehr Knochen und Knochenteile (rund 300). Warum weniger bei Erwachsenen: Viele davon wachsen im Lauf der Kindheit zusammen, zum Beispiel am Schädel.', q: W + 'Skelett_des_Menschen' },
  { id: 'n9', k: 'natur', t: 'reihe', n: 2, f: 'Ordne die Planeten nach ihrem Abstand von der Sonne (nächster zuerst):', r: ['Erde', 'Mars', 'Jupiter', 'Saturn'],
    e: 'Die Reihenfolge lautet Merkur, Venus, Erde, Mars, Jupiter, Saturn, Uranus, Neptun. Merksatz: „Mein Vater erklärt mir jeden Sonntag unseren Nachthimmel.“ Zwischen Mars und Jupiter liegt der Asteroidengürtel.', q: W + 'Sonnensystem' },
  { id: 'n10', k: 'natur', t: 'mc', n: 3, f: 'Wer beschrieb 1953 die Doppelhelix-Struktur der DNA?', a: 'James Watson und Francis Crick', x: ['Gregor Mendel', 'Charles Darwin', 'Louis Pasteur und Robert Koch'], tx: ['Watson und Crick', 'Watson', 'Crick'],
    e: 'Watson und Crick nutzten dafür wesentlich Röntgenaufnahmen von Rosalind Franklin. Warum wichtig: Die Struktur erklärt, wie Erbinformation kopiert wird. Gregor Mendel entdeckte schon im 19. Jahrhundert die Vererbungsregeln.', q: W + 'Desoxyribonukleinsäure' },
  { id: 'n11', k: 'natur', t: 'wf', n: 1, f: 'Im Weltall (Vakuum) kann sich Schall nicht ausbreiten.', w: true,
    e: 'Stimmt. Schall ist eine Schwingung von Teilchen, etwa von Luft. Im Vakuum gibt es keine Teilchen, die schwingen könnten. Explosionsgeräusche in Weltraumfilmen sind daher physikalisch falsch.', q: W + 'Schall' },

  // ───────── POLITIK & GESELLSCHAFT ─────────
  { id: 'p1', k: 'politik', t: 'mc', n: 1, f: 'Wie viele Mitgliedstaaten hat die Europäische Union?', a: '27', x: ['25', '28', '30'], tx: ['27', 'siebenundzwanzig'], st: 2025, ab: '2027-12-31',
    e: 'Seit dem Austritt Großbritanniens (Brexit) Anfang 2020 sind es 27. Zuletzt beigetreten ist Kroatien (2013). Mehrere Länder wie Montenegro, Serbien und die Ukraine sind Beitrittskandidaten.', q: W + 'Europäische_Union' },
  { id: 'p2', k: 'politik', t: 'mc', n: 1, f: 'In welcher Stadt haben die Vereinten Nationen (UNO) ihren Hauptsitz?', a: 'New York', x: ['Genf', 'Wien', 'Brüssel'], tx: ['New York'],
    e: 'Der Hauptsitz steht seit 1952 in New York. Wien ist mit der UNO-City einer von vier großen UN-Amtssitzen, die anderen sind Genf und Nairobi. In Wien sitzt zum Beispiel die Internationale Atomenergiebehörde (IAEO).', q: W + 'Vereinte_Nationen' },
  { id: 'p3', k: 'politik', t: 'mc', n: 2, f: 'Wie viele ständige Mitglieder hat der UN-Sicherheitsrat?', a: '5', x: ['3', '7', '10'], tx: ['5', 'fünf'],
    e: 'Die ständigen Mitglieder sind USA, Russland, China, Frankreich und Großbritannien, also die Siegermächte des Zweiten Weltkriegs. Warum umstritten: Jedes dieser Länder hat ein Vetorecht und kann Beschlüsse allein blockieren.', q: W + 'Sicherheitsrat_der_Vereinten_Nationen' },
  { id: 'p4', k: 'politik', t: 'mc', n: 2, f: 'Was bedeutet „Gewaltenteilung“?', a: 'Die Staatsmacht wird auf Gesetzgebung, Regierung und Gerichte aufgeteilt', x: ['Die Polizei darf keine Waffen tragen', 'Bund und Länder teilen sich die Steuern', 'Jede Partei bekommt gleich viele Sitze'],
    e: 'Legislative (Parlament), Exekutive (Regierung, Verwaltung) und Judikative (Gerichte) kontrollieren sich gegenseitig. Warum: Niemand soll zu viel Macht in einer Hand bündeln. Die Idee machte vor allem Montesquieu im 18. Jahrhundert bekannt.', q: W + 'Gewaltenteilung' },
  { id: 'p5', k: 'politik', t: 'wf', n: 2, f: 'In Österreich darf man bei Nationalratswahlen schon ab 16 Jahren wählen.', w: true,
    e: 'Stimmt, seit 2007. Österreich war damit das erste EU-Land mit Wahlalter 16 auf Bundesebene. Für die Kandidatur (passives Wahlrecht) muss man 18 sein.', q: W + 'Wahlrecht' },
  { id: 'p6', k: 'politik', t: 'mc', n: 3, f: 'Wo ist der offizielle Sitz des Europäischen Parlaments?', a: 'Straßburg', x: ['Brüssel', 'Luxemburg', 'Frankfurt am Main'], tx: ['Straßburg', 'Strassburg', 'Strasbourg'],
    e: 'Die großen Plenarsitzungen finden in Straßburg statt, Ausschüsse und weitere Sitzungen in Brüssel, das Sekretariat sitzt in Luxemburg. Das ständige Pendeln wird wegen der Kosten oft kritisiert. In Frankfurt sitzt die Europäische Zentralbank.', q: W + 'Europäisches_Parlament' },
  { id: 'p7', k: 'politik', t: 'mc', n: 3, f: 'In welchem Jahr wurde die NATO gegründet?', a: '1949', x: ['1945', '1955', '1961'], tx: ['1949'],
    e: 'Die NATO entstand zu Beginn des Kalten Krieges als Verteidigungsbündnis westlicher Staaten. Kern ist Artikel 5: Ein Angriff auf ein Mitglied gilt als Angriff auf alle. Als Gegenstück gründete der Ostblock 1955 den Warschauer Pakt.', q: W + 'NATO' },
  { id: 'p8', k: 'politik', t: 'mc', n: 1, f: 'Welches Dokument verkündete 1948 grundlegende Rechte für alle Menschen weltweit?', a: 'Allgemeine Erklärung der Menschenrechte', x: ['Genfer Konvention', 'Magna Carta', 'Kyoto-Protokoll'], tx: ['Allgemeine Erklärung der Menschenrechte', 'Erklärung der Menschenrechte', 'Menschenrechtserklärung'],
    e: 'Die UN-Generalversammlung beschloss sie am 10. Dezember 1948, deshalb ist der 10. Dezember der Tag der Menschenrechte. Sie ist nicht direkt rechtlich bindend, wurde aber Vorbild für viele Verfassungen und Verträge.', q: W + 'Allgemeine_Erklärung_der_Menschenrechte' },
  { id: 'p9', k: 'politik', t: 'mc', n: 2, f: 'Wie viele Sterne hat die Europaflagge?', a: '12', x: ['27', '15', '10'], tx: ['12', 'zwölf'],
    e: 'Die Zahl 12 hat nichts mit der Zahl der Mitglieder zu tun. Sie steht als Symbol für Vollkommenheit und Einheit und bleibt immer gleich, egal wie viele Länder beitreten.', q: W + 'Europaflagge' },
  { id: 'p10', k: 'politik', t: 'wf', n: 2, f: 'Die Schweiz ist Mitglied der Europäischen Union.', w: false,
    e: 'Falsch. Die Schweiz ist kein EU-Mitglied, hat aber viele bilaterale Verträge mit der EU und gehört zum Schengen-Raum (keine Grenzkontrollen). Sie ist auch Mitglied der EFTA.', q: W + 'Schweiz' },

  // ───────── WIRTSCHAFT & FINANZEN ─────────
  { id: 'w1', k: 'wirtschaft', t: 'mc', n: 1, f: 'Was bedeutet Inflation?', a: 'Die Preise steigen allgemein, das Geld verliert an Kaufkraft', x: ['Die Preise sinken allgemein', 'Die Zinsen steigen auf über 10 %', 'Der Staat druckt keine Geldscheine mehr'],
    e: 'Bei 3 % Inflation kostet ein Warenkorb nach einem Jahr 3 % mehr, mit gleichem Geld kann man also weniger kaufen. Deshalb verliert Geld am Sparbuch real an Wert, wenn der Zins unter der Inflation liegt.', q: W + 'Inflation' },
  { id: 'w2', k: 'wirtschaft', t: 'mc', n: 2, f: 'Welche Inflationsrate strebt die Europäische Zentralbank (EZB) mittelfristig an?', a: '2 %', x: ['0 %', '1 %', '5 %'], tx: ['2', '2 %', '2%', 'zwei Prozent'], st: 2025, ab: '2030-12-31',
    e: 'Die EZB zielt auf 2 % mittelfristig. Warum nicht 0 %: Leicht steigende Preise gelten als gesünder als sinkende (Deflation), weil Menschen bei sinkenden Preisen Käufe aufschieben und die Wirtschaft bremsen. Ihr wichtigstes Werkzeug ist der Leitzins.', q: W + 'Europäische_Zentralbank' },
  { id: 'w3', k: 'wirtschaft', t: 'mc', n: 2, f: 'Was ist ein ETF?', a: 'Ein an der Börse gehandelter Fonds, der meist einen Index nachbildet', x: ['Eine einzelne Aktie eines Technologiekonzerns', 'Ein Sparbuch mit fixem Zinssatz', 'Eine staatliche Anleihe'],
    e: 'ETF steht für „Exchange Traded Fund“. Ein ETF auf den MSCI World kauft zum Beispiel automatisch Anteile von über 1.000 Unternehmen. Warum beliebt: breite Streuung bei niedrigen Kosten, weil kein Fondsmanager aktiv auswählt.', q: W + 'Indexfonds' },
  { id: 'w4', k: 'wirtschaft', t: 'mc', n: 2, f: 'Was misst das Bruttoinlandsprodukt (BIP)?', a: 'Den Wert aller in einem Land in einem Zeitraum hergestellten Waren und Dienstleistungen', x: ['Die Staatsschulden eines Landes', 'Das Vermögen aller Einwohner', 'Die Summe aller Exporte'],
    e: 'Das BIP ist die wichtigste Kennzahl für die Wirtschaftsleistung. Steigt es, spricht man von Wachstum. Sinkt es zwei Quartale in Folge, spricht man meist von einer Rezession. Es sagt aber nichts über Verteilung oder Lebensqualität aus.', q: W + 'Bruttoinlandsprodukt' },
  { id: 'w5', k: 'wirtschaft', t: 'wf', n: 1, f: 'Zinseszins bedeutet, dass auch auf bereits erhaltene Zinsen wieder Zinsen gezahlt werden.', w: true,
    e: 'Stimmt. Beispiel: 1.000 € mit 7 % pro Jahr werden nach 10 Jahren zu rund 1.967 €, nicht nur zu 1.700 €. Warum das wichtig ist: Je früher man anlegt, desto stärker wirkt der Effekt. Das ist der Hauptgrund für langfristiges Investieren.', q: W + 'Zinseszins' },
  { id: 'w6', k: 'wirtschaft', t: 'mc', n: 1, f: 'Seit welchem Jahr gibt es Euro-Münzen und -Scheine als Bargeld?', a: '2002', x: ['1999', '1995', '2004'], tx: ['2002'],
    e: 'Als Buchgeld (Überweisungen, Börse) gibt es den Euro seit 1999, das Bargeld kam am 1. Jänner 2002. In Österreich wurde dabei der Schilling umgerechnet: 1 Euro = 13,7603 Schilling.', q: W + 'Euro' },
  { id: 'w7', k: 'wirtschaft', t: 'mc', n: 2, f: 'Was bedeutet „Diversifikation“ beim Investieren?', a: 'Das Geld auf viele verschiedene Anlagen verteilen, um das Risiko zu senken', x: ['Alles in die Aktie mit der besten Rendite stecken', 'Nur in Gold investieren', 'Aktien besonders oft kaufen und verkaufen'],
    e: 'Nach dem Motto „nicht alle Eier in einen Korb legen“: Geht ein Unternehmen pleite, fällt das bei breiter Streuung kaum ins Gewicht. Diversifikation senkt das Risiko, ohne die erwartete Rendite stark zu senken.', q: W + 'Diversifikation_(Wirtschaft)' },
  { id: 'w8', k: 'wirtschaft', t: 'mc', n: 2, f: 'Was beschreibt ein „Bullenmarkt“ an der Börse?', a: 'Einen Markt mit lang anhaltend steigenden Kursen', x: ['Einen Markt mit stark fallenden Kursen', 'Den Handel mit Agrarprodukten', 'Einen Markt ohne Schwankungen'],
    e: 'Eine Eselsbrücke: Der Bulle stößt mit den Hörnern nach oben (steigende Kurse), der Bär schlägt mit der Pranke nach unten (fallende Kurse). Vor der Frankfurter Börse stehen deshalb Bulle und Bär als Statuen.', q: W + 'Bullen-_und_Bärenmarkt' },
  { id: 'w9', k: 'wirtschaft', t: 'mc', n: 3, f: 'Nach ungefähr wie vielen Jahren verdoppelt sich Geld bei 6 % Rendite pro Jahr?', a: 'nach ca. 12 Jahren', x: ['nach ca. 6 Jahren', 'nach ca. 18 Jahren', 'nach ca. 24 Jahren'], tx: ['12', '12 Jahre', 'zwölf'],
    e: 'Faustregel (72er-Regel): 72 geteilt durch den Zinssatz ergibt die Jahre bis zur Verdopplung, hier 72 ÷ 6 = 12. Das gilt dank Zinseszins. Bei 8 % wären es rund 9 Jahre.', q: W + 'Zinseszins' },
  { id: 'w10', k: 'wirtschaft', t: 'wf', n: 1, f: 'Wer eine Aktie kauft, wird Miteigentümer des Unternehmens.', w: true,
    e: 'Stimmt. Eine Aktie ist ein Anteil am Unternehmen. Aktionäre bekommen oft eine Gewinnbeteiligung (Dividende) und dürfen auf der Hauptversammlung abstimmen. Im Gegensatz dazu leiht man bei einer Anleihe dem Unternehmen nur Geld.', q: W + 'Aktie' },

  // ───────── KUNST & LITERATUR ─────────
  { id: 'k1', k: 'kunst', t: 'mc', n: 1, f: 'Wer malte die Mona Lisa?', a: 'Leonardo da Vinci', x: ['Michelangelo', 'Raffael', 'Sandro Botticelli'], tx: ['Leonardo da Vinci', 'Leonardo', 'da Vinci'],
    e: 'Leonardo malte sie Anfang des 16. Jahrhunderts, heute hängt sie im Louvre in Paris. Weltberühmt wurde sie auch durch ihren Diebstahl 1911: Das Bild war zwei Jahre verschwunden.', q: W + 'Mona_Lisa' },
  { id: 'k2', k: 'kunst', t: 'mc', n: 1, f: 'Wer schrieb das Drama „Faust“?', a: 'Johann Wolfgang von Goethe', x: ['Friedrich Schiller', 'Gotthold Ephraim Lessing', 'Franz Kafka'], tx: ['Goethe', 'Johann Wolfgang von Goethe'],
    e: 'Goethe arbeitete fast sein ganzes Leben daran, Teil 2 erschien erst nach seinem Tod 1832. Faust verkauft dem Teufel Mephisto seine Seele für Erkenntnis und Genuss. Daher kommt der Ausdruck „Pakt mit dem Teufel“.', q: W + 'Johann_Wolfgang_von_Goethe' },
  { id: 'k3', k: 'kunst', t: 'mc', n: 2, f: 'Welcher Wiener Maler schuf das goldene Gemälde „Der Kuss“?', a: 'Gustav Klimt', x: ['Egon Schiele', 'Oskar Kokoschka', 'Friedensreich Hundertwasser'], tx: ['Klimt', 'Gustav Klimt'],
    e: 'Klimt malte „Der Kuss“ 1908/09 in seiner „Goldenen Phase“ mit echtem Blattgold. Es hängt im Belvedere in Wien. Klimt war Mitbegründer der Wiener Secession, Schiele war sein Schützling.', q: W + 'Der_Kuss_(Klimt)' },
  { id: 'k4', k: 'kunst', t: 'mc', n: 1, f: 'Wer schrieb „Romeo und Julia“?', a: 'William Shakespeare', x: ['Charles Dickens', 'Molière', 'Christopher Marlowe'], tx: ['Shakespeare', 'William Shakespeare'],
    e: 'Shakespeare schrieb die Tragödie um 1595, sie spielt in Verona. Er prägte die englische Sprache stark: Viele Wörter und Redewendungen tauchen bei ihm zum ersten Mal schriftlich auf.', q: W + 'William_Shakespeare' },
  { id: 'k5', k: 'kunst', t: 'mc', n: 2, f: 'Wer malte „Die Sternennacht“ (1889)?', a: 'Vincent van Gogh', x: ['Claude Monet', 'Paul Cézanne', 'Paul Gauguin'], tx: ['van Gogh', 'Vincent van Gogh', 'Van Gogh'],
    e: 'Van Gogh malte es während eines Aufenthalts in einer psychiatrischen Klinik in Südfrankreich, mit Blick aus seinem Fenster. Zu Lebzeiten verkaufte er kaum Bilder, heute zählen sie zu den teuersten der Welt.', q: W + 'Vincent_van_Gogh' },
  { id: 'k6', k: 'kunst', t: 'wf', n: 2, f: 'Franz Kafka schrieb seine Werke auf Tschechisch.', w: false,
    e: 'Falsch. Kafka lebte zwar in Prag, schrieb aber auf Deutsch, er gehörte zur deutschsprachigen jüdischen Minderheit. Bekannt sind „Die Verwandlung“ und „Der Process“. Das Wort „kafkaesk“ steht für undurchschaubare, bedrohliche Bürokratie.', q: W + 'Franz_Kafka' },
  { id: 'k7', k: 'kunst', t: 'mc', n: 3, f: 'Welche Kunstrichtung begründeten Pablo Picasso und Georges Braque?', a: 'Kubismus', x: ['Impressionismus', 'Surrealismus', 'Expressionismus'], tx: ['Kubismus'],
    e: 'Im Kubismus (ab ca. 1907) werden Gegenstände in geometrische Formen zerlegt und aus mehreren Blickwinkeln gleichzeitig gezeigt. Warum revolutionär: Die Kunst löste sich damit endgültig von der naturgetreuen Abbildung.', q: W + 'Kubismus' },
  { id: 'k8', k: 'kunst', t: 'mc', n: 2, f: 'Wo befindet sich die Sixtinische Kapelle mit Michelangelos Deckenfresken?', a: 'Im Vatikan', x: ['In Florenz', 'In Venedig', 'In Paris'], tx: ['Vatikan', 'Vatikanstadt', 'Rom'],
    e: 'Michelangelo bemalte die Decke von 1508 bis 1512, darunter die berühmte „Erschaffung Adams“. In der Kapelle wählen die Kardinäle beim Konklave den neuen Papst.', q: W + 'Sixtinische_Kapelle' },
  { id: 'k9', k: 'kunst', t: 'reihe', n: 3, f: 'Ordne die Kunstepochen chronologisch (früheste zuerst):', r: ['Romanik', 'Gotik', 'Renaissance', 'Barock'],
    e: 'Romanik (ca. 1000–1250, dicke Mauern, Rundbögen), Gotik (Spitzbögen, hohe Fenster, z. B. Stephansdom), Renaissance (ab ca. 1400, Wiederentdeckung der Antike), Barock (ab ca. 1600, prunkvoll, z. B. Stift Melk).', q: W + 'Barock' },
  { id: 'k10', k: 'kunst', t: 'mc', n: 2, f: 'Wer schrieb „Der kleine Prinz“?', a: 'Antoine de Saint-Exupéry', x: ['Jules Verne', 'Victor Hugo', 'Albert Camus'], tx: ['Saint-Exupéry', 'Saint-Exupery', 'Antoine de Saint-Exupéry', 'Exupery'],
    e: 'Der französische Pilot und Schriftsteller veröffentlichte das Buch 1943. Es ist eines der meistübersetzten Bücher der Welt. Saint-Exupéry verschwand 1944 bei einem Aufklärungsflug über dem Mittelmeer.', q: W + 'Der_kleine_Prinz' },

  // ───────── MUSIK & FILM ─────────
  { id: 'm1', k: 'musikfilm', t: 'mc', n: 1, f: 'In welcher Stadt wurde Wolfgang Amadeus Mozart geboren?', a: 'Salzburg', x: ['Wien', 'Linz', 'Innsbruck'], tx: ['Salzburg'],
    e: 'Mozart kam 1756 in der Getreidegasse in Salzburg zur Welt, damals ein eigenes Fürsterzbistum. Später lebte er in Wien, wo er 1791 mit nur 35 Jahren starb. Er schrieb über 600 Werke.', q: W + 'Wolfgang_Amadeus_Mozart' },
  { id: 'm2', k: 'musikfilm', t: 'mc', n: 1, f: 'Welcher Komponist schrieb die 9. Sinfonie mit der „Ode an die Freude“, obwohl er fast taub war?', a: 'Ludwig van Beethoven', x: ['Joseph Haydn', 'Johannes Brahms', 'Franz Schubert'], tx: ['Beethoven', 'Ludwig van Beethoven'],
    e: 'Beethoven vollendete die 9. Sinfonie 1824 in Wien. Die Melodie der „Ode an die Freude“ ist heute die Europahymne. Er verlor ab etwa 30 Jahren zunehmend sein Gehör und komponierte trotzdem weiter.', q: W + 'Ludwig_van_Beethoven' },
  { id: 'm3', k: 'musikfilm', t: 'mc', n: 2, f: 'Welche Stadt gilt als Geburtsort des Techno (Mitte der 1980er-Jahre)?', a: 'Detroit', x: ['Berlin', 'Chicago', 'Manchester'], tx: ['Detroit'],
    e: 'Juan Atkins, Derrick May und Kevin Saunderson („Belleville Three“) prägten in Detroit den „Detroit Techno“, beeinflusst von Funk und europäischer Elektronik wie Kraftwerk. Chicago ist die Geburtsstadt von House. Berlin wurde nach dem Mauerfall zur Techno-Hauptstadt Europas.', q: W + 'Detroit_Techno' },
  { id: 'm4', k: 'musikfilm', t: 'mc', n: 2, f: 'Aus welchem Land stammt Hardstyle hauptsächlich?', a: 'Niederlande', x: ['Deutschland', 'Großbritannien', 'Schweden'], tx: ['Niederlande', 'Holland'],
    e: 'Hardstyle entstand Ende der 1990er-Jahre vor allem in den Niederlanden und in Italien, als Mischung aus Hard Trance und Hardcore. Typisch sind der verzerrte „Kick“ und ein Tempo um 150 BPM. Große Events wie Defqon.1 finden in den Niederlanden statt.', q: 'https://en.wikipedia.org/wiki/Hardstyle' },
  { id: 'm5', k: 'musikfilm', t: 'mc', n: 1, f: 'Wer führte Regie bei „Der weiße Hai“ und „Jurassic Park“?', a: 'Steven Spielberg', x: ['George Lucas', 'Martin Scorsese', 'James Cameron'], tx: ['Spielberg', 'Steven Spielberg'],
    e: '„Der weiße Hai“ (1975) gilt als erster „Blockbuster“, also als Film, der im Sommer massenhaft Publikum zieht. Spielberg drehte auch „E.T.“ und „Schindlers Liste“, für den er 1994 den Regie-Oscar bekam.', q: W + 'Steven_Spielberg' },
  { id: 'm6', k: 'musikfilm', t: 'wf', n: 2, f: 'Der Donauwalzer („An der schönen blauen Donau“) stammt von Johann Strauss (Sohn).', w: true,
    e: 'Stimmt. Strauss Sohn komponierte ihn 1867. Er gilt als heimliche Hymne Österreichs und wird jedes Jahr als Zugabe beim Neujahrskonzert der Wiener Philharmoniker gespielt. Sein Vater komponierte den Radetzky-Marsch.', q: W + 'An_der_schönen_blauen_Donau' },
  { id: 'm7', k: 'musikfilm', t: 'mc', n: 2, f: 'Wie viele Tasten hat ein normales Klavier?', a: '88', x: ['76', '96', '108'], tx: ['88'],
    e: 'Es sind 52 weiße und 36 schwarze Tasten, zusammen gut 7 Oktaven. Dieser Umfang hat sich Ende des 19. Jahrhunderts als Standard durchgesetzt.', q: W + 'Klavier' },
  { id: 'm8', k: 'musikfilm', t: 'mc', n: 1, f: 'Welche Band brachte 1969 das Album „Abbey Road“ heraus?', a: 'The Beatles', x: ['The Rolling Stones', 'Queen', 'Pink Floyd'], tx: ['Beatles', 'The Beatles'],
    e: 'Das Cover mit den vier Bandmitgliedern auf dem Zebrastreifen vor dem Londoner Studio in der Abbey Road ist eines der bekanntesten der Musikgeschichte. Kurz darauf trennte sich die Band.', q: W + 'The_Beatles' },
  { id: 'm9', k: 'musikfilm', t: 'mc', n: 2, f: 'Auf welchem Filmfestival wird der „Goldene Bär“ verliehen?', a: 'Berlinale (Berlin)', x: ['Filmfestspiele Cannes', 'Filmfestspiele Venedig', 'Viennale (Wien)'], tx: ['Berlinale', 'Berlin'],
    e: 'Der Bär ist das Wappentier Berlins. In Cannes gibt es die Goldene Palme, in Venedig den Goldenen Löwen. Diese drei gelten als die wichtigsten Filmfestivals Europas.', q: W + 'Internationale_Filmfestspiele_Berlin' },
  { id: 'm10', k: 'musikfilm', t: 'mc', n: 3, f: 'Welcher Österreicher gewann zwei Oscars als bester Nebendarsteller, unter anderem für „Inglourious Basterds“?', a: 'Christoph Waltz', x: ['Klaus Maria Brandauer', 'Arnold Schwarzenegger', 'Michael Haneke'], tx: ['Christoph Waltz', 'Waltz'],
    e: 'Waltz gewann 2010 für „Inglourious Basterds“ und 2013 für „Django Unchained“, beide Male unter Regisseur Quentin Tarantino. Michael Haneke gewann mit „Liebe“ den Oscar für den besten fremdsprachigen Film.', q: W + 'Christoph_Waltz' },

  // ───────── SPORT ─────────
  { id: 's1', k: 'sport', t: 'mc', n: 1, f: 'Wie viele Spieler einer Fußballmannschaft stehen gleichzeitig auf dem Feld?', a: '11', x: ['10', '9', '12'], tx: ['11', 'elf'],
    e: 'Elf Spieler inklusive Tormann. Hat eine Mannschaft durch Ausschlüsse weniger als sieben Spieler, wird das Spiel abgebrochen.', q: W + 'Fußball' },
  { id: 's2', k: 'sport', t: 'mc', n: 1, f: 'Wie oft finden Olympische Sommerspiele statt?', a: 'Alle 4 Jahre', x: ['Alle 2 Jahre', 'Jedes Jahr', 'Alle 5 Jahre'],
    e: 'Sommer- und Winterspiele finden je alle vier Jahre statt, seit 1994 aber um zwei Jahre versetzt, sodass alle zwei Jahre Olympia ist. Der Vierjahres-Rhythmus geht auf die antiken Spiele zurück, die „Olympiade“ war ursprünglich der Zeitraum dazwischen.', q: W + 'Olympische_Spiele' },
  { id: 's3', k: 'sport', t: 'mc', n: 2, f: 'Wie lang ist ein Marathon?', a: '42,195 km', x: ['40 km', '42 km', '45 km'], tx: ['42,195', '42.195', '42,195 km', '42195'],
    e: 'Der Name geht auf die Legende eines Boten zurück, der von Marathon nach Athen lief. Die krumme Länge wurde bei den Spielen 1908 in London festgelegt: Der Start lag beim Schloss Windsor, das Ziel vor der Königsloge.', q: W + 'Marathonlauf' },
  { id: 's4', k: 'sport', t: 'mc', n: 2, f: 'Wie oft wurde Niki Lauda Formel-1-Weltmeister?', a: '3-mal', x: ['1-mal', '2-mal', '4-mal'], tx: ['3', 'drei', 'dreimal'],
    e: 'Lauda wurde 1975, 1977 und 1984 Weltmeister. 1976 überlebte er auf dem Nürburgring einen schweren Feuerunfall und saß sechs Wochen später wieder im Auto. Der Film „Rush“ erzählt diese Saison.', q: W + 'Niki_Lauda' },
  { id: 's5', k: 'sport', t: 'wf', n: 2, f: 'Die fünf Olympischen Ringe stehen für die fünf Erdteile, die durch den Sport verbunden sind.', w: true,
    e: 'Stimmt. Pierre de Coubertin entwarf das Symbol 1913. Die fünf Ringe stehen für Afrika, Amerika, Asien, Australien/Ozeanien und Europa. Einzelne Ringe sind aber keinem bestimmten Kontinent zugeordnet. Die Farben mit dem weißen Hintergrund sollten alle Nationalflaggen der Zeit abdecken.', q: W + 'Olympische_Ringe' },
  { id: 's6', k: 'sport', t: 'mc', n: 2, f: 'Wo fanden 1896 die ersten Olympischen Spiele der Neuzeit statt?', a: 'Athen', x: ['Paris', 'London', 'Olympia'], tx: ['Athen'],
    e: 'Die Spiele fanden bewusst in Griechenland statt, als Anknüpfung an die antiken Spiele in Olympia. Österreich war schon 1896 dabei. Paris folgte 1900, London 1908.', q: W + 'Olympische_Sommerspiele_1896' },
  { id: 's7', k: 'sport', t: 'mc', n: 3, f: 'Welcher Österreicher gewann 2020 die US Open im Tennis?', a: 'Dominic Thiem', x: ['Thomas Muster', 'Jürgen Melzer', 'Dennis Novak'], tx: ['Thiem', 'Dominic Thiem'],
    e: 'Thiem war damit der zweite Österreicher mit einem Grand-Slam-Titel im Einzel. Der erste war Thomas Muster mit den French Open 1995, Muster war 1996 sogar Nummer 1 der Weltrangliste.', q: W + 'Dominic_Thiem' },
  { id: 's8', k: 'sport', t: 'mc', n: 2, f: 'In welchem Ort findet das berühmte Abfahrtsrennen auf der „Streif“ statt?', a: 'Kitzbühel', x: ['Schladming', 'Wengen', 'Sölden'], tx: ['Kitzbühel', 'Kitzbuehel'],
    e: 'Das Hahnenkammrennen in Kitzbühel gilt als schwierigste Abfahrt im Weltcup, mit Stellen wie der „Mausefalle“ und bis zu 85 % Gefälle. In Wengen (Schweiz) liegt das Lauberhorn, in Schladming findet das Nightrace statt.', q: W + 'Hahnenkammrennen' },
  { id: 's9', k: 'sport', t: 'mc', n: 3, f: 'Wie viele Punkte bringt ein Touchdown im American Football?', a: '6', x: ['3', '7', '2'], tx: ['6', 'sechs'],
    e: 'Danach darf die Mannschaft einen Zusatzversuch machen: ein Kick durch die Torstangen bringt 1 Punkt, ein weiterer Lauf oder Pass in die Endzone 2 Punkte. Ein Field Goal ist 3 Punkte wert.', q: W + 'Touchdown' },
  { id: 's10', k: 'sport', t: 'wf', n: 2, f: 'Ein Basketballkorb hängt 3,05 Meter hoch.', w: true,
    e: 'Stimmt, das sind genau 10 Fuß. Die Höhe stammt noch vom Erfinder James Naismith, der 1891 Pfirsichkörbe an einem Turnhallen-Balkon befestigte und seither nie angepasst wurde.', q: W + 'Basketball' },

  // ───────── NATUR & TIERE ─────────
  { id: 't1', k: 'tiere', t: 'mc', n: 1, f: 'Welches ist das größte Tier, das je auf der Erde gelebt hat?', a: 'Blauwal', x: ['Pottwal', 'Argentinosaurus (Dinosaurier)', 'Walhai'], tx: ['Blauwal'],
    e: 'Blauwale werden bis zu rund 30 m lang und weit über 100 Tonnen schwer, schwerer als jeder bekannte Dinosaurier. Warum möglich: Im Wasser trägt der Auftrieb das Gewicht. Sie fressen trotzdem fast nur winzigen Krill.', q: W + 'Blauwal' },
  { id: 't2', k: 'tiere', t: 'mc', n: 1, f: 'Welches ist das schnellste Landtier?', a: 'Gepard', x: ['Löwe', 'Gabelbock', 'Windhund'], tx: ['Gepard'],
    e: 'Geparden erreichen auf kurzen Sprints rund 100 km/h, halten das aber nur wenige hundert Meter durch. Der Gabelbock ist langsamer, kann aber viel länger schnell laufen.', q: W + 'Gepard' },
  { id: 't3', k: 'tiere', t: 'wf', n: 2, f: 'Fledermäuse sind die einzigen Säugetiere, die aktiv fliegen können.', w: true,
    e: 'Stimmt. „Flughörnchen“ können nur gleiten. Fledermäuse orientieren sich mit Ultraschall (Echoortung). In Österreich leben rund 28 Fledermausarten, alle sind streng geschützt.', q: W + 'Fledertiere' },
  { id: 't4', k: 'tiere', t: 'mc', n: 2, f: 'Wie viele Herzen hat ein Oktopus (Krake)?', a: '3', x: ['1', '2', '8'], tx: ['3', 'drei'],
    e: 'Zwei Herzen pumpen Blut durch die Kiemen, eines durch den restlichen Körper. Ihr Blut ist blau, weil es Kupfer statt Eisen zum Sauerstofftransport nutzt. Kraken gelten als die intelligentesten wirbellosen Tiere.', q: W + 'Kraken' },
  { id: 't5', k: 'tiere', t: 'mc', n: 1, f: 'Welches Gas geben Pflanzen bei der Photosynthese ab?', a: 'Sauerstoff', x: ['Kohlendioxid', 'Stickstoff', 'Wasserstoff'], tx: ['Sauerstoff', 'O2'],
    e: 'Pflanzen nehmen Kohlendioxid und Wasser auf und bauen mit Sonnenlicht Zucker daraus. Sauerstoff entsteht dabei als „Abfall“. Ein großer Teil des Sauerstoffs stammt übrigens nicht aus Wäldern, sondern aus Algen im Meer.', q: W + 'Photosynthese' },
  { id: 't6', k: 'tiere', t: 'wf', n: 1, f: 'Wale sind Fische.', w: false,
    e: 'Falsch. Wale sind Säugetiere: Sie atmen Luft mit Lungen, sind warmblütig und säugen ihre Jungen. Ihre Vorfahren lebten an Land. Man erkennt den Unterschied auch an der Schwanzflosse: Bei Walen steht sie waagrecht, bei Fischen senkrecht.', q: W + 'Wale' },
  { id: 't7', k: 'tiere', t: 'mc', n: 3, f: 'Wie lange ist ein Elefant ungefähr trächtig?', a: 'ca. 22 Monate', x: ['ca. 9 Monate', 'ca. 12 Monate', 'ca. 30 Monate'],
    e: 'Elefanten haben die längste Tragzeit aller Landsäugetiere. Warum so lang: Das Kalb kommt mit rund 100 kg und weit entwickeltem Gehirn zur Welt und kann bald nach der Geburt mit der Herde mitlaufen.', q: W + 'Elefanten' },
  { id: 't8', k: 'tiere', t: 'mc', n: 2, f: 'Welcher Vogel kann auch rückwärts fliegen?', a: 'Kolibri', x: ['Schwalbe', 'Mauersegler', 'Specht'], tx: ['Kolibri'],
    e: 'Kolibris können ihre Flügel im Schultergelenk drehen und mit bis zu rund 80 Schlägen pro Sekunde in der Luft stehen. So schweben sie vor Blüten und trinken Nektar.', q: W + 'Kolibris' },
  { id: 't9', k: 'tiere', t: 'mc', n: 1, f: 'Woran kann man das Alter eines gefällten Baumes ablesen?', a: 'An den Jahresringen im Stamm', x: ['An der Zahl der Äste', 'An der Dicke der Rinde', 'An der Länge der Wurzeln'], tx: ['Jahresringe', 'Jahresringen'],
    e: 'Im Frühjahr wächst helles, lockeres Holz, im Spätsommer dunkleres, dichteres. So entsteht pro Jahr ein Ring. Breite Ringe zeigen gute Jahre, schmale trockene oder kalte Jahre. Forscher datieren damit sogar alte Holzbalken.', q: W + 'Jahresring' },
  { id: 't10', k: 'tiere', t: 'wf', n: 3, f: 'Haie gehören zu den Knochenfischen.', w: false,
    e: 'Falsch. Haie sind Knorpelfische, ihr Skelett besteht aus Knorpel statt Knochen. Das macht sie leichter und beweglicher. Rochen gehören ebenfalls dazu. Karpfen, Hecht und Forelle sind dagegen Knochenfische.', q: W + 'Haie' },

  // ───────── SPRACHE ─────────
  { id: 'sp1', k: 'sprache', t: 'mc', n: 1, f: 'Was bedeutet „Carpe diem“?', a: 'Nutze den Tag', x: ['Gott sei mit dir', 'Ich kam, sah und siegte', 'Im Wein liegt die Wahrheit'], tx: ['Nutze den Tag', 'Pflücke den Tag', 'Genieße den Tag'],
    e: 'Der lateinische Spruch stammt vom römischen Dichter Horaz, wörtlich „Pflücke den Tag“. „Ich kam, sah und siegte“ ist „Veni, vidi, vici“ (Caesar), „Im Wein liegt die Wahrheit“ ist „In vino veritas“.', q: W + 'Carpe_diem' },
  { id: 'sp2', k: 'sprache', t: 'mc', n: 1, f: 'Was ist ein Palindrom?', a: 'Ein Wort, das vorwärts und rückwärts gleich lautet', x: ['Ein Wort mit zwei gegensätzlichen Bedeutungen', 'Ein Gedicht ohne Reim', 'Ein Wort aus einer fremden Sprache'], tx: ['vorwärts und rückwärts gleich'],
    e: 'Beispiele: „Otto“, „Rentner“, „Anna“, „Reliefpfeiler“. Das Wort kommt aus dem Griechischen und bedeutet etwa „zurücklaufend“.', q: W + 'Palindrom' },
  { id: 'sp3', k: 'sprache', t: 'mc', n: 2, f: 'Was bedeutet „Paradigmenwechsel“?', a: 'Ein grundlegender Wechsel der Denkweise oder Sichtweise', x: ['Ein Wechsel der Regierungspartei', 'Ein kleiner Fehler in einer Rechnung', 'Ein Austausch von Bauteilen'],
    e: 'Der Begriff stammt vom Wissenschaftsphilosophen Thomas Kuhn (1962). Klassisches Beispiel ist der Wechsel vom Weltbild mit der Erde im Mittelpunkt zu dem mit der Sonne im Mittelpunkt (Kopernikus).', q: W + 'Paradigmenwechsel' },
  { id: 'sp4', k: 'sprache', t: 'mc', n: 2, f: 'Welche Sprache hat die meisten Muttersprachler weltweit?', a: 'Mandarin-Chinesisch', x: ['Englisch', 'Spanisch', 'Hindi'], tx: ['Mandarin', 'Chinesisch', 'Mandarin-Chinesisch'], st: 2025, ab: '2030-12-31',
    e: 'Mandarin hat rund eine Milliarde Muttersprachler. Zählt man aber alle Sprecher mit (auch Fremdsprache), liegt Englisch vorne. Spanisch ist bei den Muttersprachlern auf Platz 2.', q: W + 'Liste_der_meistgesprochenen_Sprachen' },
  { id: 'sp5', k: 'sprache', t: 'wf', n: 2, f: 'Das deutsche Wort „Kindergarten“ wird auch im Englischen verwendet.', w: true,
    e: 'Stimmt. Friedrich Fröbel gründete 1840 den ersten „Kindergarten“, die Idee und das Wort wanderten danach in viele Sprachen. Weitere Beispiele für Deutsch im Englischen: „Angst“, „Zeitgeist“, „Wanderlust“.', q: W + 'Kindergarten' },
  { id: 'sp6', k: 'sprache', t: 'mc', n: 3, f: 'Was ist ein Euphemismus?', a: 'Eine beschönigende Umschreibung', x: ['Eine starke Übertreibung', 'Ein Wort aus dem Griechischen', 'Eine Abkürzung'],
    e: 'Beispiele: „entschlafen“ statt „sterben“, „Preisanpassung“ statt „Preiserhöhung“, „freigestellt“ statt „gekündigt“. Warum man darauf achten sollte: Euphemismen werden oft gezielt eingesetzt, um Unangenehmes harmloser klingen zu lassen.', q: W + 'Euphemismus' },
  { id: 'sp7', k: 'sprache', t: 'mc', n: 2, f: 'Was bedeutet „Sisyphusarbeit“?', a: 'Eine mühsame Arbeit, die nie fertig wird', x: ['Eine besonders gut bezahlte Arbeit', 'Eine Arbeit in der Nacht', 'Eine sehr schnell erledigte Arbeit'],
    e: 'In der griechischen Sage musste Sisyphos zur Strafe einen Felsbrocken einen Berg hinaufrollen, der kurz vor dem Gipfel immer wieder hinunterrollte.', q: W + 'Sisyphos' },
  { id: 'sp8', k: 'sprache', t: 'mc', n: 1, f: 'Was bedeutet „Status quo“?', a: 'Der derzeitige Zustand', x: ['Ein hoher gesellschaftlicher Rang', 'Ein Statussymbol', 'Der frühere Zustand'],
    e: 'Lateinisch für „Zustand, in dem“. Wer „den Status quo erhalten“ will, möchte, dass alles so bleibt, wie es ist. Den früheren Zustand nennt man „Status quo ante“.', q: W + 'Status_quo' },
  { id: 'sp9', k: 'sprache', t: 'mc', n: 3, f: 'Was ist ein Oxymoron?', a: 'Eine Verbindung von zwei Begriffen, die sich widersprechen', x: ['Ein Wort mit mehreren Bedeutungen', 'Ein sehr langes zusammengesetztes Wort', 'Eine chemische Verbindung mit Sauerstoff'],
    e: 'Beispiele: „bittersüß“, „alter Knabe“, „beredtes Schweigen“, „Hassliebe“. Das griechische Wort selbst ist schon eines: „oxys“ (scharf) und „moros“ (dumm), also „scharfsinnig-dumm“.', q: W + 'Oxymoron' },
  { id: 'sp10', k: 'sprache', t: 'mc', n: 2, f: 'Was bedeutet die Abkürzung „z. Hd.“ auf einem Brief?', a: 'zu Händen', x: ['zur Hälfte', 'zum Hausdienst', 'zur Durchsicht'], tx: ['zu Händen'],
    e: '„z. Hd.“ bedeutet, dass der Brief an eine Firma geht, aber bei einer bestimmten Person landen soll. Heute schreibt man meist einfach den Namen ohne „z. Hd.“ in die Adresse.', q: W + 'Postanschrift' },

  // ───────── ÖSTERREICH-SPEZIAL ─────────
  { id: 'o1', k: 'oesterreich', t: 'mc', n: 1, f: 'Wie viele Bundesländer hat Österreich?', a: '9', x: ['8', '10', '7'], tx: ['9', 'neun'],
    e: 'Wien, Niederösterreich, Oberösterreich, Steiermark, Kärnten, Salzburg, Tirol, Vorarlberg und Burgenland. Das Burgenland kam als jüngstes erst 1921 von Ungarn zu Österreich.', q: W + 'Österreich' },
  { id: 'o2', k: 'oesterreich', t: 'mc', n: 1, f: 'Welcher ist der höchste Berg Österreichs?', a: 'Großglockner', x: ['Wildspitze', 'Großvenediger', 'Dachstein'], tx: ['Großglockner', 'Grossglockner', 'Glockner'],
    e: 'Der Großglockner ist 3.798 m hoch und liegt an der Grenze von Kärnten und Tirol in den Hohen Tauern. Zweithöchster ist die Wildspitze in den Ötztaler Alpen. Die Großglockner-Hochalpenstraße führt bis auf über 2.500 m.', q: W + 'Großglockner' },
  { id: 'o3', k: 'oesterreich', t: 'mc', n: 1, f: 'Seit welchem Jahr ist Österreich Mitglied der EU?', a: '1995', x: ['1989', '1999', '2004'], tx: ['1995'],
    e: 'Bei der Volksabstimmung 1994 stimmten rund zwei Drittel dafür, beigetreten wurde am 1. Jänner 1995, gemeinsam mit Schweden und Finnland. Den Euro als Bargeld gibt es seit 2002.', q: W + 'Österreich' },
  { id: 'o4', k: 'oesterreich', t: 'mc', n: 2, f: 'In welchem Jahr wurde der Österreichische Staatsvertrag unterzeichnet?', a: '1955', x: ['1945', '1949', '1960'], tx: ['1955'],
    e: 'Am 15. Mai 1955 unterzeichneten die vier Besatzungsmächte (USA, Sowjetunion, Großbritannien, Frankreich) im Schloss Belvedere den Vertrag. Danach zogen sie ab, und Österreich war wieder voll unabhängig.', q: W + 'Österreichischer_Staatsvertrag' },
  { id: 'o5', k: 'oesterreich', t: 'mc', n: 2, f: 'Warum ist der 26. Oktober Österreichs Nationalfeiertag?', a: 'An diesem Tag 1955 wurde das Neutralitätsgesetz beschlossen', x: ['An diesem Tag wurde der Staatsvertrag unterzeichnet', 'An diesem Tag endete die Monarchie', 'An diesem Tag trat Österreich der EU bei'],
    e: 'Am 26. Oktober 1955 beschloss der Nationalrat die immerwährende Neutralität. Am Tag davor hatten die letzten Besatzungssoldaten das Land verlassen. Der Staatsvertrag war schon am 15. Mai unterzeichnet worden.', q: W + 'Nationalfeiertag_(Österreich)' },
  { id: 'o6', k: 'oesterreich', t: 'mc', n: 2, f: 'Wer wählt in Österreich den Bundespräsidenten?', a: 'Das Volk direkt, für 6 Jahre', x: ['Der Nationalrat, für 5 Jahre', 'Die Landeshauptleute, für 4 Jahre', 'Die Bundesregierung, für 6 Jahre'],
    e: 'Der Bundespräsident wird direkt vom Volk gewählt, für sechs Jahre, mit höchstens einer Wiederwahl. Er ernennt unter anderem den Bundeskanzler und ist Oberbefehlshaber des Bundesheeres.', q: W + 'Bundespräsident_(Österreich)' },
  { id: 'o7', k: 'oesterreich', t: 'wf', n: 2, f: 'Der Neusiedler See ist der größte See, der vollständig in Österreich liegt.', w: false,
    e: 'Falsch. Der Neusiedler See ist zwar der größte See Österreichs, ein Teil im Süden gehört aber zu Ungarn. Der größte See, der komplett in Österreich liegt, ist der Attersee in Oberösterreich.', q: W + 'Attersee' },
  { id: 'o8', k: 'oesterreich', t: 'mc', n: 2, f: 'Welche Habsburger-Herrscherin führte 1774 die allgemeine Schulpflicht ein?', a: 'Maria Theresia', x: ['Kaiserin Elisabeth („Sisi“)', 'Marie Antoinette', 'Zita von Bourbon-Parma'], tx: ['Maria Theresia'],
    e: 'Maria Theresia regierte von 1740 bis 1780 und modernisierte Verwaltung, Heer und Schulwesen. Sie hatte 16 Kinder, darunter Marie Antoinette, die spätere Königin von Frankreich.', q: W + 'Maria_Theresia' },
  { id: 'o9', k: 'oesterreich', t: 'mc', n: 3, f: 'Wie viele Einwohner hat Österreich ungefähr?', a: 'ca. 9,2 Millionen', x: ['ca. 7,5 Millionen', 'ca. 8,1 Millionen', 'ca. 10,5 Millionen'], tx: ['9,2', '9,2 Millionen', '9 Millionen'], st: 2025, ab: '2028-12-31',
    e: 'Laut Statistik Austria lebten Anfang 2025 rund 9,2 Millionen Menschen in Österreich, etwa 2 Millionen davon in Wien. Das Wachstum kommt hauptsächlich durch Zuwanderung.', q: W + 'Österreich' },
  { id: 'o10', k: 'oesterreich', t: 'reihe', n: 3, f: 'Ordne chronologisch (früheste zuerst):', r: ['Ende der Monarchie, Ausrufung der Republik (1918)', '„Anschluss“ an das Deutsche Reich (1938)', 'Staatsvertrag (1955)', 'EU-Beitritt (1995)'],
    e: '1918 zerfiel Österreich-Ungarn, die Republik Deutschösterreich wurde ausgerufen. 1938 wurde Österreich an das nationalsozialistische Deutschland angeschlossen, 1945 entstand die Zweite Republik. 1955 folgten Staatsvertrag und Neutralität, 1995 der EU-Beitritt.', q: W + 'Geschichte_Österreichs' },
];
